import customers from './customers.json' with {type:'json'};

const TOOL_NAME = 'customer_lookup';

const customerLookupTool = {
  name: TOOL_NAME,
  description: 'Look up a customer profile by their customer_id.',
  inputSchema: {
    type: 'object',
    properties: {
      customer_id: {
        type: 'string',
        description: 'The unique identifier of the customer to look up.',
      },
    },
    required: ['customer_id'],
    additionalProperties: false,
  },
};

export async function listTools() {
  return [customerLookupTool];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected a JSON object');
  }

  const { customer_id } = args;

  if (typeof customer_id !== 'string' || customer_id.length === 0) {
    throw new Error('Invalid arguments: customer_id must be a non-empty string');
  }

  if (!Object.prototype.hasOwnProperty.call(customers, customer_id)) {
    throw new Error(`Unknown customer: ${customer_id}`);
  }

  const profile = customers[customer_id];
  const text = JSON.stringify(profile);
  return { content: [{ type: 'text', text }] };
}

